package contract

import (
	"regexp"
	"strings"
	"unicode"
)

var camelBoundary = regexp.MustCompile(`([a-z0-9])([A-Z])`)

var extraSuccessStems = map[string]struct{}{
	"succeeded-recurring": {},
	"succeeded-one-time":  {},
	"succeeded-bare":      {},
	"processing":          {},
	"timeout":             {},
	"failed":              {},
	"cancelled":           {},
}

func CamelToKebab(value string) string {
	return strings.ToLower(camelBoundary.ReplaceAllString(value, "${1}-${2}"))
}

func allUpperWithLetter(value string) bool {
	hasLetter := false
	for _, r := range value {
		if unicode.IsLetter(r) {
			hasLetter = true
			if unicode.IsLower(r) {
				return false
			}
		}
	}
	return hasLetter
}

func CamelToSnake(value string) string {
	if allUpperWithLetter(value) {
		return value
	}
	return strings.ToLower(camelBoundary.ReplaceAllString(value, "${1}_${2}"))
}

func IsSuccessCase(fileStem string) bool {
	if strings.HasPrefix(fileStem, "success") || strings.HasPrefix(fileStem, "by-") {
		return true
	}
	_, ok := extraSuccessStems[fileStem]
	return ok
}

func IsErrorCase(fileStem string) bool {
	return strings.HasPrefix(fileStem, "error") || fileStem == "no-match" || fileStem == "missing-params"
}

