package contract

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// FixtureErrorExpect is `expect.error` from a golden fixture.
type FixtureErrorExpect struct {
	Message string
	Name    *string
	Status  *int
	Kind    *string
	Code    *string
}

// WireRequest is `wire.request`.
type WireRequest struct {
	Method  string
	Path    string
	Query   map[string]string
	Headers map[string]string
	Body    any
}

// WireResponse is `wire.response`.
type WireResponse struct {
	Status int
	Body   any
}

// Wire is the programmed HTTP exchange for a client fixture.
type Wire struct {
	Request  WireRequest
	Response WireResponse
}

// FixtureInput is `input`.
type FixtureInput struct {
	Fn      string
	Args    map[string]any
	Clock   string
	RngSeed *int
}

// Fixture is one §5.3 golden fixture.
type Fixture struct {
	Suite        string
	Case         string
	Input        FixtureInput
	ExpectKind   string
	ExpectResult any
	ExpectError  *FixtureErrorExpect
	Wire         *Wire
	Path         string
}

// FindRepoRoot walks parents until `contract/fixtures` is found.
func FindRepoRoot(start string) (string, error) {
	cur, err := filepath.Abs(start)
	if err != nil {
		return "", err
	}
	info, err := os.Stat(cur)
	if err != nil {
		return "", err
	}
	if !info.IsDir() {
		cur = filepath.Dir(cur)
	}
	for {
		if st, err := os.Stat(filepath.Join(cur, "contract", "fixtures")); err == nil && st.IsDir() {
			return cur, nil
		}
		parent := filepath.Dir(cur)
		if parent == cur {
			return "", fmt.Errorf("could not locate repo root containing contract/fixtures")
		}
		cur = parent
	}
}

// DiscoverFixtureFiles returns sorted JSON paths under fixturesRoot.
func DiscoverFixtureFiles(fixturesRoot string) ([]string, error) {
	var files []string
	err := filepath.WalkDir(fixturesRoot, func(path string, d os.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() || !strings.HasSuffix(path, ".json") {
			return nil
		}
		files = append(files, path)
		return nil
	})
	if err != nil {
		return nil, err
	}
	sort.Strings(files)
	return files, nil
}

// LoadFixture reads and validates one golden fixture file.
func LoadFixture(path string) (Fixture, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return Fixture{}, err
	}
	var obj map[string]any
	if err := json.Unmarshal(raw, &obj); err != nil {
		return Fixture{}, err
	}
	return parseFixture(obj, path)
}

func parseFixture(raw map[string]any, path string) (Fixture, error) {
	suite, err := requireString(raw, "suite")
	if err != nil {
		return Fixture{}, err
	}
	caseName, err := requireString(raw, "case")
	if err != nil {
		return Fixture{}, err
	}
	inputRaw, ok := raw["input"].(map[string]any)
	if !ok {
		return Fixture{}, fmt.Errorf("fixture.input must be an object")
	}
	fn, err := requireString(inputRaw, "fn")
	if err != nil {
		return Fixture{}, err
	}
	args := map[string]any{}
	if argsRaw, exists := inputRaw["args"]; exists && argsRaw != nil {
		m, ok := argsRaw.(map[string]any)
		if !ok {
			return Fixture{}, fmt.Errorf("fixture.input.args must be an object")
		}
		args = m
	}
	clock := ""
	if c, exists := inputRaw["clock"]; exists && c != nil {
		s, ok := c.(string)
		if !ok || s == "" {
			return Fixture{}, fmt.Errorf("fixture.input.clock must be a non-empty string when present")
		}
		clock = s
	}
	var rngSeed *int
	if v, exists := inputRaw["rngSeed"]; exists && v != nil {
		n, ok := asInt(v)
		if !ok {
			return Fixture{}, fmt.Errorf("fixture.input.rngSeed must be an int when present")
		}
		rngSeed = &n
	}

	expectRaw, ok := raw["expect"].(map[string]any)
	if !ok {
		return Fixture{}, fmt.Errorf("fixture.expect must be an object")
	}
	_, hasResult := expectRaw["result"]
	_, hasError := expectRaw["error"]
	if hasResult == hasError {
		return Fixture{}, fmt.Errorf("expect must contain exactly one of result or error")
	}

	out := Fixture{
		Suite: suite,
		Case:  caseName,
		Input: FixtureInput{Fn: fn, Args: args, Clock: clock, RngSeed: rngSeed},
		Path:  path,
	}
	if hasResult {
		out.ExpectKind = "result"
		out.ExpectResult = expectRaw["result"]
	} else {
		out.ExpectKind = "error"
		errObj, ok := expectRaw["error"].(map[string]any)
		if !ok {
			return Fixture{}, fmt.Errorf("expect.error must be an object")
		}
		msg, ok := errObj["message"].(string)
		if !ok {
			return Fixture{}, fmt.Errorf("expect.error.message must be a string")
		}
		fe := &FixtureErrorExpect{Message: msg}
		if s, err := optionalString(errObj, "name"); err != nil {
			return Fixture{}, err
		} else if s != "" {
			fe.Name = &s
		}
		if n, err := optionalInt(errObj, "status"); err != nil {
			return Fixture{}, err
		} else if n != nil {
			fe.Status = n
		}
		if s, err := optionalString(errObj, "kind"); err != nil {
			return Fixture{}, err
		} else if s != "" {
			fe.Kind = &s
		}
		if s, err := optionalString(errObj, "code"); err != nil {
			return Fixture{}, err
		} else if s != "" {
			fe.Code = &s
		}
		out.ExpectError = fe
	}

	if w, exists := raw["wire"]; exists && w != nil {
		wire, err := parseWire(w)
		if err != nil {
			return Fixture{}, err
		}
		out.Wire = &wire
	}
	return out, nil
}

func parseWire(raw any) (Wire, error) {
	obj, ok := raw.(map[string]any)
	if !ok {
		return Wire{}, fmt.Errorf("wire must be an object")
	}
	req, ok := obj["request"].(map[string]any)
	if !ok {
		return Wire{}, fmt.Errorf("wire.request and wire.response are required objects")
	}
	resp, ok := obj["response"].(map[string]any)
	if !ok {
		return Wire{}, fmt.Errorf("wire.request and wire.response are required objects")
	}
	method, _ := req["method"].(string)
	switch method {
	case "GET", "POST", "PUT", "PATCH", "DELETE":
	default:
		return Wire{}, fmt.Errorf("wire.request.method must be an HTTP verb")
	}
	path, err := requireString(req, "path")
	if err != nil {
		return Wire{}, err
	}
	var query map[string]string
	if q, exists := req["query"]; exists && q != nil {
		qm, ok := q.(map[string]any)
		if !ok {
			return Wire{}, fmt.Errorf("wire.request.query must be an object when present")
		}
		query = stringMap(qm)
	}
	var headers map[string]string
	if h, exists := req["headers"]; exists && h != nil {
		hm, ok := h.(map[string]any)
		if !ok {
			return Wire{}, fmt.Errorf("wire.request.headers must be an object when present")
		}
		headers = stringMap(hm)
	}
	status, ok := asInt(resp["status"])
	if !ok {
		return Wire{}, fmt.Errorf("wire.response.status must be an int")
	}
	if _, ok := resp["body"]; !ok {
		return Wire{}, fmt.Errorf("wire.response.body is required")
	}
	return Wire{
		Request: WireRequest{
			Method:  method,
			Path:    path,
			Query:   query,
			Headers: headers,
			Body:    req["body"],
		},
		Response: WireResponse{Status: status, Body: resp["body"]},
	}, nil
}

func requireString(obj map[string]any, key string) (string, error) {
	value, ok := obj[key].(string)
	if !ok || value == "" {
		return "", fmt.Errorf("%s must be a non-empty string", key)
	}
	return value, nil
}

func optionalString(obj map[string]any, key string) (string, error) {
	value, exists := obj[key]
	if !exists || value == nil {
		return "", nil
	}
	s, ok := value.(string)
	if !ok || s == "" {
		return "", fmt.Errorf("%s must be a non-empty string when present", key)
	}
	return s, nil
}

func optionalInt(obj map[string]any, key string) (*int, error) {
	value, exists := obj[key]
	if !exists || value == nil {
		return nil, nil
	}
	n, ok := asInt(value)
	if !ok {
		return nil, fmt.Errorf("%s must be an int when present", key)
	}
	return &n, nil
}

func asInt(v any) (int, bool) {
	switch n := v.(type) {
	case int:
		return n, true
	case int64:
		return int(n), true
	case float64:
		if n == float64(int(n)) {
			return int(n), true
		}
	}
	return 0, false
}

func stringMap(obj map[string]any) map[string]string {
	out := make(map[string]string, len(obj))
	for k, v := range obj {
		out[k] = fmt.Sprint(v)
	}
	return out
}

