package contract

import (
	"encoding/json"
	"errors"
	"fmt"
	"reflect"

	solvapay "github.com/solvapay/solvapay-go"
	"github.com/solvapay/solvapay-go/internal/nativecall"
)

var webhookCodes = map[string]struct{}{
	"invalid_signature":   {},
	"timestamp_too_old":   {},
	"malformed_signature": {},
	"missing_signature":   {},
	"invalid_payload":     {},
}

// Outcome is a normalized fixture result.
type Outcome struct {
	OK           bool
	Value        any
	ErrorName    string
	ErrorMessage string
	ErrorStatus  *int
	ErrorKind    string
	ErrorCode    string
}

// OutcomeFromValue wraps a successful call.
func OutcomeFromValue(value any) Outcome {
	return Outcome{OK: true, Value: value}
}

// OutcomeFromError maps a Go error onto the fixture error surface.
func OutcomeFromError(err error) Outcome {
	var jsErr *plainError
	if errors.As(err, &jsErr) {
		return Outcome{OK: false, ErrorName: "Error", ErrorMessage: jsErr.msg}
	}
	code, message, statusN, kindHint := "", "", 0, ""
	var svErr *solvapay.Error
	var ge *nativecall.GuestError
	switch {
	case errors.As(err, &svErr):
		code, message, statusN = svErr.Code, svErr.Message, svErr.Status
	case errors.As(err, &ge):
		code, message, statusN, kindHint = ge.Code, ge.Message, ge.Status, ge.Kind
	default:
		return Outcome{OK: false, ErrorName: fmt.Sprintf("%T", err), ErrorMessage: err.Error()}
	}
	name := "SolvaPayError"
	kind := kindHint
	if code == "Paywall" || kind == "Paywall" {
		name = "PaywallError"
		kind = "Paywall"
	}
	if _, ok := webhookCodes[code]; ok {
		kind = "Webhook"
		name = "SolvaPayError"
	}
	var status *int
	if statusN != 0 {
		status = &statusN
		if kind == "" {
			kind = "Api"
		}
	}
	if kind == "" && (code == "Transport" || code == "retryable" || code == "non_retryable") {
		kind = "Transport"
	}
	return Outcome{
		OK:           false,
		ErrorName:    name,
		ErrorMessage: message,
		ErrorStatus:  status,
		ErrorKind:    kind,
		ErrorCode:    code,
	}
}

type plainError struct{ msg string }

func (e *plainError) Error() string { return e.msg }

// JSONEq is deep equality with numeric coercion (`25` == `25.0`).
func JSONEq(left, right any) bool {
	if left == nil || right == nil {
		return left == nil && right == nil
	}
	if isNumber(left) && isNumber(right) {
		return asFloat(left) == asFloat(right)
	}
	lv, rv := reflect.ValueOf(left), reflect.ValueOf(right)
	if lv.Kind() == reflect.Slice && rv.Kind() == reflect.Slice {
		if lv.Len() != rv.Len() {
			return false
		}
		for i := 0; i < lv.Len(); i++ {
			if !JSONEq(lv.Index(i).Interface(), rv.Index(i).Interface()) {
				return false
			}
		}
		return true
	}
	lm, lok := asMap(left)
	rm, rok := asMap(right)
	if lok && rok {
		if len(lm) != len(rm) {
			return false
		}
		for k, v := range lm {
			ov, ok := rm[k]
			if !ok || !JSONEq(v, ov) {
				return false
			}
		}
		return true
	}
	return reflect.DeepEqual(left, right)
}

func isNumber(v any) bool {
	switch v.(type) {
	case int, int8, int16, int32, int64, uint, uint8, uint16, uint32, uint64, float32, float64:
		return true
	default:
		return false
	}
}

func asFloat(v any) float64 {
	switch n := v.(type) {
	case int:
		return float64(n)
	case int64:
		return float64(n)
	case float32:
		return float64(n)
	case float64:
		return n
	default:
		rv := reflect.ValueOf(v)
		switch rv.Kind() {
		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
			return float64(rv.Int())
		case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
			return float64(rv.Uint())
		case reflect.Float32, reflect.Float64:
			return rv.Float()
		}
	}
	return 0
}

func asMap(v any) (map[string]any, bool) {
	if m, ok := v.(map[string]any); ok {
		return m, true
	}
	return nil, false
}

// AssertExpect compares a replay outcome against fixture.expect.
func AssertExpect(outcome Outcome, fixture Fixture) error {
	if fixture.ExpectKind == "result" {
		if !outcome.OK {
			return fmt.Errorf("expected result, got error name=%q message=%q", outcome.ErrorName, outcome.ErrorMessage)
		}
		got, err := jsonRoundtrip(outcome.Value)
		if err != nil {
			return err
		}
		want, err := jsonRoundtrip(fixture.ExpectResult)
		if err != nil {
			return err
		}
		if !JSONEq(got, want) {
			return fmt.Errorf("result mismatch:\n  got:      %#v\n  expected: %#v", got, want)
		}
		return nil
	}
	expected := fixture.ExpectError
	if expected == nil {
		return fmt.Errorf("missing expect.error")
	}
	if outcome.OK {
		return fmt.Errorf("expected error %q, got success %#v", expected.Message, outcome.Value)
	}
	return assertError(outcome, expected)
}

func assertError(actual Outcome, expected *FixtureErrorExpect) error {
	if actual.ErrorMessage != expected.Message {
		return fmt.Errorf("error message mismatch: got %q, expected %q", actual.ErrorMessage, expected.Message)
	}
	if expected.Name != nil && actual.ErrorName != *expected.Name {
		return fmt.Errorf("error name mismatch: got %q, expected %q", actual.ErrorName, *expected.Name)
	}
	if expected.Status != nil {
		if actual.ErrorStatus == nil || *actual.ErrorStatus != *expected.Status {
			return fmt.Errorf("error status mismatch: got %v, expected %d", actual.ErrorStatus, *expected.Status)
		}
	}
	if expected.Kind != nil && actual.ErrorKind != *expected.Kind {
		return fmt.Errorf("error kind mismatch: got %q, expected %q", actual.ErrorKind, *expected.Kind)
	}
	if expected.Code != nil && actual.ErrorCode != *expected.Code {
		return fmt.Errorf("error code mismatch: got %q, expected %q", actual.ErrorCode, *expected.Code)
	}
	return nil
}

func jsonRoundtrip(v any) (any, error) {
	if v == nil {
		return nil, nil
	}
	raw, err := json.Marshal(v)
	if err != nil {
		return nil, err
	}
	var out any
	if err := json.Unmarshal(raw, &out); err != nil {
		return nil, err
	}
	return out, nil
}

