package contract

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
)

// CapturedRequest is one HTTP call recorded by StubBackend.
type CapturedRequest struct {
	Method string
	Path   string
}

// StubBackend serves one programmed response and records method/path.
type StubBackend struct {
	Status   int
	Body     any
	Captured []CapturedRequest
	server   *httptest.Server
}

// Start launches the stub server.
func (s *StubBackend) Start() {
	backend := s
	s.server = httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		backend.Captured = append(backend.Captured, CapturedRequest{
			Method: r.Method,
			// EscapedPath keeps encodeURIComponent segments (%2F) so wire
			// fixtures match the bytes the client sent (SEC-003).
			Path: r.URL.EscapedPath(),
		})
		payload := backend.Body
		var data []byte
		contentType := "application/json"
		switch v := payload.(type) {
		case nil:
			data = []byte{}
			contentType = "application/octet-stream"
		case string:
			data = []byte(v)
			contentType = "text/plain; charset=utf-8"
		default:
			encoded, err := json.Marshal(v)
			if err != nil {
				http.Error(w, err.Error(), http.StatusInternalServerError)
				return
			}
			data = encoded
			if len(data) > 0 && data[0] == '"' {
				var str string
				if err := json.Unmarshal(data, &str); err == nil {
					data = []byte(str)
				}
			}
		}
		w.Header().Set("Content-Type", contentType)
		w.WriteHeader(backend.Status)
		if r.Method != http.MethodHead && len(data) > 0 {
			_, _ = io.WriteString(w, string(data))
		}
	}))
}

// BaseURL is the stub origin.
func (s *StubBackend) BaseURL() string {
	if s.server == nil {
		panic("stub backend is not running")
	}
	return s.server.URL
}

// Close shuts the stub down.
func (s *StubBackend) Close() {
	if s.server != nil {
		s.server.Close()
		s.server = nil
	}
}

// AssertWireRequest checks method and path only.
//
// Go's ClientConfig cannot inject clockMs / rngSeed, so header and body
// assertions (seeded idempotency keys) are not expressible.
func AssertWireRequest(actual CapturedRequest, expected WireRequest) error {
	if actual.Method != expected.Method {
		return fmt.Errorf("wire.request.method mismatch: %q != %q", actual.Method, expected.Method)
	}
	if actual.Path != expected.Path {
		return fmt.Errorf("wire.request.path mismatch: %q != %q", actual.Path, expected.Path)
	}
	return nil
}

