package contract

import (
	"context"
	"encoding/json"
	"fmt"
	"strconv"

	"github.com/solvapay/solvapay-go/internal/nativecall"
)

var TopupBalancePollDelaysMS = []int{500, 1000, 2000, 4000}
var BalanceReconcileDelaysMS = []int{500, 1000, 2000, 4000, 8000, 16000}

var HostFns = map[string]struct{}{
{{HOST_FNS}}
}

// InvokeHost runs a host-side adapter for orchestration fixtures.
func InvokeHost(ctx context.Context, fn string, args map[string]any, clock string) (any, error) {
	switch fn {
	case "withRetry":
		return invokeWithRetry(ctx, args)
	case "pollBalanceUntilIncreased":
		return invokePollBalance(args)
	case "TOPUP_BALANCE_POLL_DELAYS_MS":
		return append([]int(nil), TopupBalancePollDelaysMS...), nil
	case "BALANCE_RECONCILE_DELAYS_MS":
		return append([]int(nil), BalanceReconcileDelaysMS...), nil
	case "resolveAuthenticatedUser":
		payload := copyMap(args)
		if clock != "" {
			secs, err := UnixSecs(clock)
			if err != nil {
				return nil, err
			}
			payload["nowUnixSecs"] = secs
		} else if _, ok := payload["nowUnixSecs"]; !ok {
			payload["nowUnixSecs"] = int64(1_700_000_000)
		}
		raw, err := json.Marshal(payload)
		if err != nil {
			return nil, err
		}
		return nativecall.CallSync(ctx, "sv_resolve_authenticated_user", string(raw))
	default:
		return nil, fmt.Errorf("no host adapter for %s", fn)
	}
}

func invokeWithRetry(ctx context.Context, args map[string]any) (map[string]any, error) {
	attempts, ok := args["attempts"].([]any)
	if !ok || len(attempts) == 0 {
		return nil, fmt.Errorf("withRetry args.attempts must be a non-empty array")
	}
	options, _ := args["options"].(map[string]any)
	maxRetries := 2
	initialDelay := 500
	backoff := "fixed"
	if options != nil {
		if v, ok := asInt(options["maxRetries"]); ok {
			maxRetries = v
		}
		if v, ok := asInt(options["initialDelay"]); ok {
			initialDelay = v
		}
		if v, ok := options["backoffStrategy"].(string); ok {
			backoff = v
		}
	}
	shouldRetry := args["shouldRetry"]
	onRetry, _ := args["onRetry"].(bool)

	events := []any{}
	delays := []any{}
	callIndex := 0
	for {
		attempt := callIndex
		events = append(events, fmt.Sprintf("call:%d", attempt))
		var spec any
		if callIndex < len(attempts) {
			spec = attempts[callIndex]
		}
		callIndex++

		if m, ok := spec.(map[string]any); ok {
			if v, exists := m["resolve"]; exists {
				return map[string]any{
					"delays":  delays,
					"events":  events,
					"outcome": map[string]any{"type": "resolved", "value": v},
				}, nil
			}
		}

		var errorMessage string
		if m, ok := spec.(map[string]any); ok {
			if v, exists := m["throw"]; exists {
				errorMessage = fmt.Sprint(v)
			} else if v, exists := m["throwRaw"]; exists {
				errorMessage = jsStringCoerce(v)
			} else {
				return nil, fmt.Errorf("unsupported withRetry attempt spec: %#v", spec)
			}
		} else if spec == nil {
			message := fmt.Sprintf("withRetry scenario exhausted attempts at call:%d", attempt)
			return map[string]any{
				"delays":  delays,
				"events":  events,
				"outcome": map[string]any{"type": "rejected", "name": "Error", "message": message},
			}, nil
		} else {
			return nil, fmt.Errorf("unsupported withRetry attempt spec: %#v", spec)
		}

		delayArgs, err := json.Marshal(map[string]any{
			"attempt":         attempt,
			"maxRetries":      maxRetries,
			"initialDelay":    initialDelay,
			"backoffStrategy": backoff,
		})
		if err != nil {
			return nil, err
		}
		delay, err := nativecall.CallSync(ctx, "sv_retry_next_delay_ms", string(delayArgs))
		if err != nil {
			return nil, err
		}
		if delay == nil {
			return map[string]any{
				"delays": delays,
				"events": events,
				"outcome": map[string]any{
					"type":    "rejected",
					"name":    "Error",
					"message": errorMessage,
				},
			}, nil
		}

		if shouldRetry != nil {
			allow, err := decideShouldRetry(shouldRetry, attempt)
			if err != nil {
				return nil, err
			}
			flag := "false"
			if allow {
				flag = "true"
			}
			events = append(events, fmt.Sprintf("shouldRetry:%d=%s", attempt, flag))
			if !allow {
				return map[string]any{
					"delays": delays,
					"events": events,
					"outcome": map[string]any{
						"type":    "rejected",
						"name":    "Error",
						"message": errorMessage,
					},
				}, nil
			}
		}

		if onRetry {
			events = append(events, fmt.Sprintf("onRetry:%d", attempt))
		}

		delayN, ok := asInt(delay)
		if !ok {
			return nil, fmt.Errorf("retry delay is not an int: %#v", delay)
		}
		delays = append(delays, delayN)
		events = append(events, fmt.Sprintf("sleep:%d", delayN))
	}
}

func decideShouldRetry(spec any, attempt int) (bool, error) {
	if spec == "always" {
		return true, nil
	}
	if spec == "never" {
		return false, nil
	}
	if m, ok := spec.(map[string]any); ok {
		if veto, ok := m["vetoAt"].([]any); ok {
			for _, x := range veto {
				n, ok := asInt(x)
				if ok && n == attempt {
					return false, nil
				}
			}
			return true, nil
		}
	}
	return false, fmt.Errorf("unsupported shouldRetry spec: %#v", spec)
}

func jsStringCoerce(value any) string {
	if value == nil {
		return "null"
	}
	switch v := value.(type) {
	case bool:
		if v {
			return "true"
		}
		return "false"
	case string:
		return v
	case float64:
		if v == float64(int(v)) {
			return strconv.Itoa(int(v))
		}
		return strconv.FormatFloat(v, 'g', -1, 64)
	case int:
		return strconv.Itoa(v)
	default:
		return "[object Object]"
	}
}

func invokePollBalance(args map[string]any) (map[string]any, error) {
	baseline, ok := asFloatPtr(args["baseline"])
	if !ok {
		return nil, fmt.Errorf("pollBalanceUntilIncreased args.baseline must be a number")
	}
	observations, ok := args["observations"].([]any)
	if !ok {
		return nil, fmt.Errorf("pollBalanceUntilIncreased args.observations must be an array")
	}
	delays, err := parsePollDelays(args["delays"])
	if err != nil {
		return nil, err
	}

	recorded := []any{}
	obsIndex := 0
	for _, delay := range delays {
		recorded = append(recorded, delay)
		if obsIndex >= len(observations) {
			continue
		}
		item, ok := observations[obsIndex].(map[string]any)
		obsIndex++
		if !ok {
			return nil, fmt.Errorf("observation must be an object")
		}
		if _, exists := item["throw"]; exists {
			continue
		}
		creditsRaw, exists := item["credits"]
		if !exists {
			return nil, fmt.Errorf("observation needs credits or throw")
		}
		credits, ok := asFloatPtr(creditsRaw)
		if !ok {
			return nil, fmt.Errorf("observation.credits must be a number")
		}
		delta := credits - baseline
		if delta > 0 {
			var creditsAdded any = delta
			if delta == float64(int(delta)) {
				creditsAdded = int(delta)
			}
			return map[string]any{"delays": recorded, "result": map[string]any{"creditsAdded": creditsAdded}}, nil
		}
	}
	return map[string]any{"delays": recorded, "result": nil}, nil
}

func parsePollDelays(raw any) ([]int, error) {
	if raw == nil || raw == "reconcile" {
		return append([]int(nil), BalanceReconcileDelaysMS...), nil
	}
	if raw == "topup" {
		return append([]int(nil), TopupBalancePollDelaysMS...), nil
	}
	if list, ok := raw.([]any); ok {
		out := make([]int, 0, len(list))
		for _, x := range list {
			n, ok := asInt(x)
			if !ok {
				return nil, fmt.Errorf("unsupported poll delays: %#v", raw)
			}
			out = append(out, n)
		}
		return out, nil
	}
	return nil, fmt.Errorf("unsupported poll delays: %#v", raw)
}

func asFloatPtr(v any) (float64, bool) {
	if isNumber(v) {
		return asFloat(v), true
	}
	return 0, false
}

func copyMap(in map[string]any) map[string]any {
	out := make(map[string]any, len(in))
	for k, v := range in {
		out[k] = v
	}
	return out
}

