package contract

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"

	solvapay "github.com/solvapay/solvapay-go"
	"github.com/solvapay/solvapay-go/internal/dispatch"
	"github.com/solvapay/solvapay-go/internal/nativecall"
)

const apiKey = "sk_test_fixture"

// ErrUnsupported means the fixture fn is not routed on this surface.
var ErrUnsupported = errors.New("unsupported fixture fn")

var SyncExports = map[string]string{
{{SYNC_EXPORTS}}
}

// Replay runs one fixture and returns a normalized outcome (does not assert expect).
func Replay(ctx context.Context, fixture Fixture) (Outcome, error) {
	fn := fixture.Input.Fn
	if fn == "verifyWebhook" {
		value, err := dispatchWebhook(ctx, fixture)
		if err != nil {
			return OutcomeFromError(err), nil
		}
		return OutcomeFromValue(value), nil
	}
	if fn == "constructSdkError" {
		return dispatchConstructSdkError(ctx, fixture)
	}
	if _, ok := HostFns[fn]; ok {
		value, err := InvokeHost(ctx, fn, fixture.Input.Args, fixture.Input.Clock)
		if err != nil {
			return OutcomeFromError(err), nil
		}
		return OutcomeFromValue(value), nil
	}
	if isClientFn(fn) {
		return dispatchClient(ctx, fixture)
	}
	if export, ok := SyncExports[fn]; ok {
		return dispatchSync(ctx, fixture, export)
	}
	return Outcome{}, fmt.Errorf("%w: %s", ErrUnsupported, fn)
}

func isClientFn(fn string) bool {
	name := dispatch.ToPascal(fn)
	for _, sig := range dispatch.Signatures {
		if sig.Name == name {
			return true
		}
	}
	return false
}

func dispatchConstructSdkError(ctx context.Context, fixture Fixture) (Outcome, error) {
	argsJSON, err := json.Marshal(fixture.Input.Args)
	if err != nil {
		return Outcome{}, err
	}
	raw, err := nativecall.CallEnvelope(ctx, "sv_construct_sdk_error", string(argsJSON))
	if err != nil {
		return Outcome{}, err
	}
	var envelope map[string]any
	if err := json.Unmarshal([]byte(raw), &envelope); err != nil {
		return Outcome{}, err
	}
	if envelope["ok"] != false {
		return Outcome{}, fmt.Errorf("constructSdkError must return an error envelope")
	}
	errorObj, ok := envelope["error"].(map[string]any)
	if !ok {
		return Outcome{}, fmt.Errorf("constructSdkError missing error object")
	}
	kind, _ := errorObj["kind"].(string)
	message, _ := errorObj["message"].(string)
	if message == "" {
		message = "SolvaPay error"
	}
	name := "SolvaPayError"
	if kind == "Paywall" {
		name = "PaywallError"
	}
	var code any = errorObj["code"]
	if kind == "Transport" {
		if retryable, _ := errorObj["retryable"].(bool); retryable {
			code = "retryable"
		} else {
			code = "non_retryable"
		}
	}
	codeStr := ""
	if s, ok := code.(string); ok {
		codeStr = s
	}
	var status *int
	if n, ok := asInt(errorObj["status"]); ok {
		status = &n
	}
	return Outcome{
		OK:           false,
		ErrorName:    name,
		ErrorMessage: message,
		ErrorStatus:  status,
		ErrorKind:    kind,
		ErrorCode:    codeStr,
	}, nil
}

func dispatchWebhook(ctx context.Context, fixture Fixture) (any, error) {
	args := fixture.Input.Args
	body, _ := args["body"].(string)
	signature, _ := args["signature"].(string)
	secret, _ := args["secret"].(string)
	if fixture.Input.Clock == "" {
		return nil, fmt.Errorf("input.clock is required for verifyWebhook")
	}
	now, err := UnixSecs(fixture.Input.Clock)
	if err != nil {
		return nil, err
	}
	return solvapay.VerifyWebhook(ctx, body, signature, secret, now)
}

func dispatchSync(ctx context.Context, fixture Fixture, export string) (Outcome, error) {
	args := copyMap(fixture.Input.Args)
	fn := fixture.Input.Fn
{{NOW_MS_INJECTION}}	argsJSON, err := json.Marshal(args)
	if err != nil {
		return Outcome{}, err
	}
	value, err := nativecall.CallSync(ctx, export, string(argsJSON))
	if err != nil {
		if fn == "assertResponseResult" {
			return Outcome{OK: false, ErrorName: "Error", ErrorMessage: OutcomeFromError(err).ErrorMessage}, nil
		}
		return OutcomeFromError(err), nil
	}
	if fn == "validatePublicBaseUrl" {
		if s, ok := value.(string); ok {
			return Outcome{OK: false, ErrorName: "Error", ErrorMessage: s}, nil
		}
	}
	return OutcomeFromValue(value), nil
}

func dispatchClient(ctx context.Context, fixture Fixture) (Outcome, error) {
	baseURL := "http://127.0.0.1:1"
	var stub *StubBackend
	if fixture.Wire != nil {
		stub = &StubBackend{Status: fixture.Wire.Response.Status, Body: fixture.Wire.Response.Body}
		stub.Start()
		defer stub.Close()
		baseURL = stub.BaseURL()
	}
	client, err := solvapay.NewClient(ctx, apiKey, solvapay.WithBaseURL(baseURL))
	if err != nil {
		return Outcome{}, err
	}
	defer func() { _ = client.Close(ctx) }()

	value, callErr := dispatch.Call(client, ctx, fixture.Input.Fn, fixture.Input.Args)
	var outcome Outcome
	if callErr != nil {
		outcome = OutcomeFromError(callErr)
	} else {
		outcome = OutcomeFromValue(value)
	}
	if stub != nil {
		if len(stub.Captured) != 1 {
			return Outcome{}, fmt.Errorf("wire fixture expected exactly one HTTP call, got %d", len(stub.Captured))
		}
		if err := AssertWireRequest(stub.Captured[0], fixture.Wire.Request); err != nil {
			return Outcome{}, err
		}
	}
	return outcome, nil
}
